def trans_grid(a,b):
 out=np.zeros((4,4),dtype=int)
 for r in range(4):
  for c in range(4):
   ns=[(rr,cc) for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=rr<4 and 0<=cc<4]
   if a[r,c]==b[r,c]==0 and any(a[rr,cc] for rr,cc in ns) and any(b[rr,cc] for rr,cc in ns): out[r,c]=4
 return out
