def trans_distinct(a,b):
 out=np.zeros((4,4),dtype=int)
 for r in range(4):
  for c in range(4):
   if a[r,c] or b[r,c]:continue
   ns=[(rr,cc) for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=rr<4 and 0<=cc<4]
   if any(a[rr,cc] and any((rr,cc)!=pos and b[pos] for pos in ns) for rr,cc in ns):out[r,c]=4
 return out
for i,(a,b,c) in enumerate(samples): print(i+1,np.array_equal(trans_distinct(a,b),4*c),trans_distinct(a,b))

